def db():
    c = sqlite3.connect(DB_PATH)
    c.row_factory = sqlite3.Row
    return c

def rows(cursor):
    return [dict(r) for r in cursor]

# ══════════════════════════════════════════════════════
# 5. SONG-ORDNER HELFER
# ══════════════════════════════════════════════════════
def song_dir(stem):
    d = JOBS_DIR / stem
    (d / "csv").mkdir(parents=True, exist_ok=True)
    (d / "notation").mkdir(exist_ok=True)
    (d / "primus" / "_FREDDY_TO_PRIMUS_HANDOFF").mkdir(parents=True, exist_ok=True)
    (d / "midi").mkdir(exist_ok=True)
    return d

def stem_from_filename(filename):
    stem = Path(filename).stem
    stem = re.sub(r'[^\w\-]', '_', stem)
    return stem[:60]

def song_status(d):
    csv_ok  = (d / "csv" / "notes_only.csv").exists()
    pdf     = next(d.rglob("*.pdf"),      None)
    xml     = next(d.rglob("*.musicxml"), None)
    primus  = next((d/"primus"/"_FREDDY_TO_PRIMUS_HANDOFF").glob("*.musicxml"), None)
    mid     = next((d/"midi").glob("*.mid"), None)
    files   = {}
    if csv_ok:
        for fn in ["raw_events.csv","normalized_events.csv","notes_only.csv",
                   "semantic_events.jsonl","freddy_midi_manifest.json","analysis_summary.md"]:
            p = d / "csv" / fn
            if p.exists():
                files[fn] = f"/songs/{d.name}/csv/{fn}"
    if pdf:
        files["score.pdf"]      = f"/songs/{d.name}/notation/{pdf.name}"
    if xml:
        files["score.musicxml"] = f"/songs/{d.name}/notation/{xml.name}"
    if primus:
        files["primus.musicxml"]= f"/songs/{d.name}/primus/_FREDDY_TO_PRIMUS_HANDOFF/{primus.name}"
    manifest_path = d / "csv" / "freddy_midi_manifest.json"
    meta = {}
    if manifest_path.exists():
        try:
            m = json.loads(manifest_path.read_text(encoding="utf-8"))
            t = m.get("tempo_map", [{}])
            if t: meta["bpm"] = round(t[0].get("bpm", 120), 1)
            ts = m.get("time_signature_map", [{}])
            if ts: meta["time_signature"] = f"{ts[0].get('numerator',4)}/{ts[0].get('denominator',4)}"
            meta["track_names"] = m.get("track_names", {})
            meta["tracks"]      = m.get("midi_header", {}).get("ntrks")
            meta["key_signature"]= next((ev.get("key_signature") for ev in
                                         m.get("semantic_events",[]) if ev.get("key_signature")), None)
        except: pass
    return {
        "stem": d.name, "midi_file": mid.name if mid else None,
        "csv_done": csv_ok, "pdf_done": pdf is not None,
        "xml_done": xml is not None, "primus_done": primus is not None,
        "files": files, "meta": meta,
    }

def all_songs():
    if not JOBS_DIR.exists(): return []
    return [song_status(d) for d in sorted(JOBS_DIR.iterdir()) if d.is_dir()]

