def api_status(_p):
    conn = db()
    result = {}
    for t in ["nodes","causal_chains","evidence_sources","freddy_modules"]:
        try: result[t] = conn.execute(f"SELECT COUNT(*) FROM {t}").fetchone()[0]
        except: result[t] = 0
    conn.close()
    result.update(midi_engine=MIDI_OK, note_engine=NOTE_OK, musescore=MUSESCORE_OK,
                  text_engine=TEXT_OK, scan_engine=SCAN_OK,
                  songs_count=len(list(JOBS_DIR.iterdir())) if JOBS_DIR.exists() else 0)
    return result

def api_songs_list(_p):
    return all_songs()

def api_modules(_p):
    conn = db()
    mods = rows(conn.execute("SELECT module_id,module_number,title,status FROM freddy_modules ORDER BY module_number"))
    for m in mods:
        mid = m["module_id"]
        m["node_count"]   = conn.execute("SELECT COUNT(*) FROM module_nodes WHERE module_id=?",(mid,)).fetchone()[0]
        m["chain_count"]  = conn.execute("""SELECT COUNT(*) FROM causal_chains cc
            JOIN module_nodes mn ON mn.node_id=cc.cause_node_id WHERE mn.module_id=?""",(mid,)).fetchone()[0]
        m["source_count"] = conn.execute("""SELECT COUNT(DISTINCT csm.source_id) FROM chain_source_map csm
            JOIN causal_chains cc ON cc.chain_id=csm.chain_id
            JOIN module_nodes mn ON mn.node_id=cc.cause_node_id WHERE mn.module_id=?""",(mid,)).fetchone()[0]
    conn.close()
    return mods

def api_nodes(params):
    conn = db()
    lang = params.get("lang",["de"])[0]
    mod  = params.get("module",[None])[0]
    sql  = "SELECT n.node_id,n.name,nt.label as type_label,n.primary_dimension,n.confidence_level,n.source_status,n.short_description FROM nodes n JOIN node_types nt ON nt.node_type_id=n.node_type_id"
    args = []
    if mod:
        sql += " JOIN module_nodes mn ON mn.node_id=n.node_id WHERE mn.module_id=?"
        args.append(MOD_MAP.get(mod, mod))
    nodes = rows(conn.execute(sql + " ORDER BY n.name", args))
    for node in nodes:
        if lang == "fr":
            alias = conn.execute("SELECT alias FROM entity_aliases WHERE entity_id=? AND language='fr' LIMIT 1",(node["node_id"],)).fetchone()
            node["name_display"] = alias["alias"] if alias else node["name"]
        else:
            node["name_display"] = node["name"]
    conn.close()
    return nodes

def api_chains(params):
    conn = db()
    mod  = params.get("module",[None])[0]
    sql  = """SELECT cc.chain_id,cc.title,cc.summary,cc.evidence_level,cc.confidence_level,
              cc.culture_dependency,cc.risk_of_oversimplification,
              n.name as cause_name,n.node_id as cause_id,ctx.name as context_name
              FROM causal_chains cc JOIN nodes n ON n.node_id=cc.cause_node_id
              LEFT JOIN contexts ctx ON ctx.context_id=cc.context_id"""
    args = []
    if mod:
        pm = {"M01":"BOD","M02":"EMO","M03":"SPA","M04":"WRK","M05":"REL",
              "M06":"MIG","M07":"TEC","M08":"ECO","M09":"INS","M10":"NOT"}
        p = pm.get(mod)
        if p:
            sql += " WHERE cc.chain_id LIKE ?"; args.append(f"{p}_%")
    chains = rows(conn.execute(sql + " ORDER BY cc.chain_id", args))
    for c in chains:
        c["sources"] = rows(conn.execute(
            "SELECT es.title,es.author_or_org,es.publication_year,csm.support_role FROM chain_source_map csm JOIN evidence_sources es ON es.source_id=csm.source_id WHERE csm.chain_id=?", (c["chain_id"],)))
    conn.close()
    return chains

def api_search(params):
    conn = db()
    q    = params.get("q",[""])[0].strip()
    lang = params.get("lang",["de"])[0]
    if len(q) < 2: conn.close(); return {"nodes":[],"chains":[]}
    like = f"%{q}%"
    if lang == "fr":
        nodes = rows(conn.execute("""SELECT DISTINCT n.node_id,n.name,COALESCE(ea.alias,n.name) as name_display,
            nt.label as type_label,n.confidence_level FROM nodes n
            JOIN node_types nt ON nt.node_type_id=n.node_type_id
            LEFT JOIN entity_aliases ea ON ea.entity_id=n.node_id AND ea.language='fr'
            WHERE n.name LIKE ? OR ea.alias LIKE ? LIMIT 20""",(like,like)))
    else:
        nodes = rows(conn.execute("""SELECT n.node_id,n.name,n.name as name_display,
            nt.label as type_label,n.confidence_level FROM nodes n
            JOIN node_types nt ON nt.node_type_id=n.node_type_id
            WHERE n.name LIKE ? OR n.short_description LIKE ? LIMIT 20""",(like,like)))
    chains = rows(conn.execute("""SELECT cc.chain_id,cc.title,cc.summary,cc.evidence_level,
        cc.confidence_level,n.name as cause_name FROM causal_chains cc
        JOIN nodes n ON n.node_id=cc.cause_node_id
        WHERE cc.title LIKE ? OR cc.summary LIKE ? OR n.name LIKE ? LIMIT 20""",(like,like,like)))
    conn.close()
    return {"nodes":nodes,"chains":chains}

def api_node_detail(node_id, params):
    conn = db()
    lang = params.get("lang",["de"])[0]
    node = conn.execute("SELECT n.*,nt.label as type_label FROM nodes n JOIN node_types nt ON nt.node_type_id=n.node_type_id WHERE n.node_id=?",(node_id,)).fetchone()
    if not node: conn.close(); return None
    result = dict(node)
    if lang == "fr":
        alias = conn.execute("SELECT alias FROM entity_aliases WHERE entity_id=? AND language='fr' LIMIT 1",(node_id,)).fetchone()
        result["name_display"] = alias["alias"] if alias else result["name"]
    else:
        result["name_display"] = result["name"]
    result["chains"]  = rows(conn.execute("SELECT chain_id,title,evidence_level,confidence_level FROM causal_chains WHERE cause_node_id=?",(node_id,)))
    result["modules"] = rows(conn.execute("SELECT fm.module_id,fm.title FROM module_nodes mn JOIN freddy_modules fm ON fm.module_id=mn.module_id WHERE mn.node_id=?",(node_id,)))
    result["aliases"] = rows(conn.execute("SELECT alias,language,alias_type FROM entity_aliases WHERE entity_id=?",(node_id,)))
    conn.close()
    return result

def api_chain_detail(chain_id, _p):
    conn = db()
    chain = conn.execute("""SELECT cc.*,n.name as cause_name,ctx.name as context_name
        FROM causal_chains cc JOIN nodes n ON n.node_id=cc.cause_node_id
        LEFT JOIN contexts ctx ON ctx.context_id=cc.context_id WHERE cc.chain_id=?""",(chain_id,)).fetchone()
    if not chain: conn.close(); return None
    result = dict(chain)
    result["sources"] = rows(conn.execute("SELECT es.*,csm.support_role FROM chain_source_map csm JOIN evidence_sources es ON es.source_id=csm.source_id WHERE csm.chain_id=?",(chain_id,)))
    conn.close()
    return result

def api_playback(stem):
    d = JOBS_DIR / stem
    csv_path = d / "csv" / "notes_only.csv"
    if not csv_path.exists():
        return {"error": "notes_only.csv nicht gefunden. Zuerst konvertieren."}
    notes = []
    total_duration = 0.0
    with open(csv_path, encoding="utf-8") as f:
        for row in csv.DictReader(f):
            if row.get("is_drum","").lower() == "true": continue
            try:
                note = {"pitch":int(row["note"]),"name":row.get("note_name",""),
                        "start":float(row["start_seconds"]),"duration":float(row["duration_seconds"]),
                        "velocity":int(row.get("velocity",64)),"track":row.get("track_name","")}
                notes.append(note)
                if note["start"]+note["duration"] > total_duration:
                    total_duration = note["start"]+note["duration"]
            except: continue
    manifest_path = d / "csv" / "freddy_midi_manifest.json"
    meta = {}
    if manifest_path.exists():
        try:
            m = json.loads(manifest_path.read_text(encoding="utf-8"))
            t = m.get("tempo_map",[{}])
            if t: meta["bpm"] = round(t[0].get("bpm",120),1)
            ts = m.get("time_signature_map",[{}])
            if ts: meta["time_signature"] = f"{ts[0].get('numerator',4)}/{ts[0].get('denominator',4)}"
            meta["track_names"] = m.get("track_names",{})
        except: pass
    return {"stem":stem,"notes":notes,"total_duration":round(total_duration+0.5,2),
            "note_count":len(notes),**meta}

# ══════════════════════════════════════════════════════
# 7. UPLOAD / KONVERTIERUNG
# ══════════════════════════════════════════════════════
def _parse_multipart(body, ct):
    """Gibt Liste von (filename, data) Tupeln zurück."""
    boundary = ct.split("boundary=")[-1].encode()
    parts = body.split(b"--" + boundary)
    result = []
    for part in parts:
        if b"filename=" not in part or b"\r\n\r\n" not in part: continue
        header, data = part.split(b"\r\n\r\n", 1)
        fn = re.search(rb'filename="([^"]+)"', header)
        if fn:
            result.append((fn.group(1).decode(errors="replace"), data.rstrip(b"\r\n--")))
    return result

def handle_upload_multi(body, ct):
    if "multipart" not in ct: return [{"error":"Erwartet multipart/form-data"}]
    results = []
    for filename, midi_data in _parse_multipart(body, ct):
        if not filename.lower().endswith((".mid",".midi")): continue
        if midi_data[:4] != b"MThd": continue
        stem = stem_from_filename(filename)
        d    = song_dir(stem)
        (d / "midi" / filename).write_bytes(midi_data)
        if not MIDI_OK:
            try:
                fmt  = struct.unpack('>H', midi_data[8:10])[0]
                trks = struct.unpack('>H', midi_data[10:12])[0]
                tpq  = struct.unpack('>H', midi_data[12:14])[0]
                results.append({"stem":stem,"filename":filename,"format":fmt,"tracks":trks,
                                 "ticks_per_quarter":tpq,"file_size_bytes":len(midi_data),"status":"upload_only"})
            except: results.append({"stem":stem,"filename":filename,"error":"Parse-Fehler"})
            continue
        try:
            parsed = parse_midi_file(d / "midi" / filename)
            midi_export(parsed, d / "csv")
            bpm = parsed.tempo_map[0]["bpm"] if parsed.tempo_map else 120.0
            ts  = parsed.time_signature_map[0] if parsed.time_signature_map else {"numerator":4,"denominator":4}
            key = next((ev.key_signature for ev in parsed.events if ev.event_type=="key_signature" and ev.key_signature), None)
            results.append({"stem":stem,"filename":filename,"file_size_bytes":len(midi_data),
                "format":parsed.header.format_type,"tracks":parsed.header.ntrks,
                "ticks_per_quarter":parsed.header.ticks_per_quarter,
                "note_count":len(parsed.notes),"event_count":len(parsed.events),
                "bpm":round(bpm,1),"time_signature":f"{ts['numerator']}/{ts['denominator']}",
                "key_signature":key or "—","track_names":parsed.track_names,
                "warnings":parsed.warnings[:3],"status":"csv_done"})
        except Exception as e:
            results.append({"stem":stem,"filename":filename,"error":str(e)})
    return results

def handle_musicxml_upload(body, ct):
    if not SCAN_OK: return [{"error":"scanforFREDDY nicht verfuegbar"}]
    if "multipart" not in ct: return [{"error":"Erwartet multipart/form-data"}]
    results = []
    for filename, xml_data in _parse_multipart(body, ct):
        if not filename.lower().endswith((".xml",".musicxml",".mxl")): continue
        stem = stem_from_filename(filename)
        d    = song_dir(stem)
        xml_path = d / "midi" / filename
        xml_path.write_bytes(xml_data)
        try:
            result = convert_musicxml_to_freddy(xml_path, d / "csv")
            results.append({"stem":stem,"filename":filename,"status":"csv_done",
                "note_count":result.get("note_count",0),"source":"musicxml"})
        except Exception as e:
            results.append({"stem":stem,"filename":filename,"error":str(e)})
    return results

def handle_text_upload(body, ct):
    if not TEXT_OK: return [{"error":"FREDDYtext nicht verfuegbar"}]
    if "multipart" not in ct: return [{"error":"Erwartet multipart/form-data"}]
    TEXT_EXTS = {".txt",".md",".csv",".json",".jsonl",".html",".epub"}
    results = []
    for filename, txt_data in _parse_multipart(body, ct):
        if Path(filename).suffix.lower() not in TEXT_EXTS: continue
        stem = stem_from_filename(filename)
        src  = JOBS_DIR / stem / "text_source" / filename
        src.parent.mkdir(parents=True, exist_ok=True)
        src.write_bytes(txt_data)
        out = JOBS_DIR / stem / "text_out"
        try:
            manifest = text_process_file(src, out, source_id=f"TEXT_{stem}")
            results.append({"stem":stem,"filename":filename,"status":"text_done",
                "chunks":manifest["counts"]["chunks_total"],
                "claims":manifest["counts"]["claims_total"],
                "causal":manifest["counts"]["causal_candidates_total"]})
        except Exception as e:
            results.append({"stem":stem,"filename":filename,"error":str(e)})
    return results

def musescore_convert(midi_path: Path, out_dir: Path) -> dict:
    """Konvertiert eine MIDI-Datei mit MuseScore 4 zu PDF + MusicXML."""
    stem = midi_path.stem
    pdf_path = out_dir / f"{stem}_musescore.pdf"
    xml_path = out_dir / f"{stem}_musescore.musicxml"
    errors = []
    for out_path in [pdf_path, xml_path]:
        r = _sub.run(
            [str(MUSESCORE_EXE), "-o", str(out_path), str(midi_path)],
            capture_output=True, text=True, timeout=120
        )
        if r.returncode != 0:
            errors.append(f"{out_path.suffix}: {r.stderr[:200]}")
    return {
        "pdf":  str(pdf_path)  if pdf_path.exists()  else None,
        "xml":  str(xml_path)  if xml_path.exists()  else None,
        "errors": errors,
        "renderer": "MuseScore4",
    }

def handle_note_batch(stems):
    if not NOTE_OK and not MUSESCORE_OK:
        return {"error": "Weder FREDDYnote noch MuseScore 4 verfügbar."}

    converted = []
    errors    = []

    song_list = stems if stems else [d.name for d in JOBS_DIR.iterdir() if d.is_dir()]

    for stem in song_list:
        target   = JOBS_DIR / stem
        midi_dir = target / "midi"
        midi     = next(midi_dir.glob("*.mid"), None) or next(midi_dir.glob("*.midi"), None) if midi_dir.exists() else None
        notation_dir = target / "notation"
        notation_dir.mkdir(parents=True, exist_ok=True)

        if MUSESCORE_OK and midi:
            # Primär: MuseScore 4 direkt aus MIDI
            result = musescore_convert(midi, notation_dir)
            if result["pdf"] or result["xml"]:
                # PriMus-Handoff
                if result["xml"]:
                    handoff = target / "primus" / "_FREDDY_TO_PRIMUS_HANDOFF"
                    handoff.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(result["xml"], handoff / Path(result["xml"]).name)
                converted.append(stem)
                if result["errors"]:
                    errors.extend(result["errors"])
                continue
            errors.extend(result["errors"])

        # Fallback: FREDDYnote (eigener Renderer)
        if NOTE_OK:
            csv_dir = target / "csv"
            if not csv_dir.exists():
                errors.append(f"{stem}: kein csv-Ordner"); continue
            notation_tmp = BASE_DIR / "data" / "_notation_tmp"
            notation_tmp.mkdir(exist_ok=True)
            proc = _sub.run(
                [sys.executable, str(FREDDYNOTE_PY), "batch", str(csv_dir),
                 "--out", str(notation_tmp), "--track", "all"],
                capture_output=True, text=True, timeout=300
            )
            for out_song_dir in notation_tmp.iterdir():
                if not out_song_dir.is_dir(): continue
                for f in out_song_dir.iterdir():
                    shutil.copy2(f, notation_dir / f.name)
                xml = next(notation_dir.glob("*.musicxml"), None)
                if xml:
                    handoff = target / "primus" / "_FREDDY_TO_PRIMUS_HANDOFF"
                    handoff.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(xml, handoff / xml.name)
            shutil.rmtree(notation_tmp, ignore_errors=True)
            if proc.returncode == 0:
                converted.append(stem)
            else:
                errors.append(f"{stem} (FREDDYnote): {proc.stderr[:200]}")

    return {
        "status":    "done" if not errors else ("partial" if converted else "error"),
        "renderer":  "MuseScore4" if MUSESCORE_OK else "FREDDYnote",
        "converted": converted,
        "errors":    errors,
        "songs":     all_songs(),
    }

def handle_primus_handoff(stem):
    d   = JOBS_DIR / stem
    xml = next(d.rglob("*.musicxml"), None)
    if not xml: return {"error":"Kein MusicXML gefunden. Zuerst FREDDYnote laufen lassen."}
    handoff = d / "primus" / "_FREDDY_TO_PRIMUS_HANDOFF"
    handoff.mkdir(parents=True, exist_ok=True)
    shutil.copy2(xml, handoff / xml.name)
    return {"status":"done","stem":stem,
            "musicxml":f"/songs/{stem}/primus/_FREDDY_TO_PRIMUS_HANDOFF/{xml.name}"}

# ══════════════════════════════════════════════════════
# 8. DATEI AUSLIEFERN
# ══════════════════════════════════════════════════════
def serve_file(handler, path):
    try:
        mime, _ = mimetypes.guess_type(str(path))
        mime = mime or "application/octet-stream"
        data = path.read_bytes()
    except Exception as e:
        handler.send_response(500)
        handler.send_header("Content-Type", "text/plain")
        handler.send_header("Content-Length", str(len(str(e).encode())))
        handler.end_headers()
        handler.wfile.write(str(e).encode())
        return
    handler.send_response(200)
    handler.send_header("Content-Type", mime)
    handler.send_header("Content-Length", str(len(data)))
    handler.send_header("Access-Control-Allow-Origin", "*")
    if path.suffix in ('.csv','.json','.jsonl','.md','.musicxml','.xml'):
        handler.send_header("Content-Disposition", f'attachment; filename="{path.name}"')
    handler.end_headers()
    handler.wfile.write(data)

# ══════════════════════════════════════════════════════
# 9. HTTP HANDLER
# ══════════════════════════════════════════════════════
class FREDDYHandler(http.server.BaseHTTPRequestHandler):

    def log_message(self, fmt, *args):
        sys.stderr.write(f"[FREDDY] {fmt % args}\n")

    def send_json(self, data, code=200):
        body = json.dumps(data, ensure_ascii=False, indent=2).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Access-Control-Allow-Origin", "*")
        self.end_headers()
        self.wfile.write(body)

    def do_OPTIONS(self):
        self.send_response(200)
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")
        self.end_headers()

    def do_GET(self):
        try:
            self._do_get_safe()
        except Exception as e:
            try:
                err = str(e).encode()
                self.send_response(500)
                self.send_header("Content-Type","text/plain; charset=utf-8")
                self.send_header("Content-Length", str(len(err)))
                self.end_headers()
                self.wfile.write(err)
            except: pass

    def _do_get_safe(self):
        _log("GET " + self.path)
        parsed = urllib.parse.urlparse(self.path)
        path   = parsed.path.rstrip("/") or "/"
        params = urllib.parse.parse_qs(parsed.query)

        # API-Routen
        routes = {
            "/api/status":     lambda: api_status(params),
            "/api/modules":    lambda: api_modules(params),
            "/api/nodes":      lambda: api_nodes(params),
            "/api/chains":     lambda: api_chains(params),
            "/api/search":     lambda: api_search(params),
            "/api/midi/songs": lambda: api_songs_list(params),
            "/debug": lambda: {"frozen":getattr(sys,"frozen",False),"_MEIPASS":str(getattr(sys,"_MEIPASS","N/A")),"exe":str(sys.executable),"_APP":str(_APP),"WEB_DIR":str(WEB_DIR),"WEB_exists":WEB_DIR.exists(),"HTML_bytes":len(_INDEX_HTML),"DB":str(DB_PATH),"DB_ok":DB_PATH.exists()},
        }
        if path in routes:
            return self.send_json(routes[path]())

        m = re.match(r"^/api/node/([A-Z0-9_]+)$", path)
        if m:
            d = api_node_detail(m.group(1), params)
            return self.send_json(d) if d else self.send_json({"error":"nicht gefunden"},404)

        m = re.match(r"^/api/chain/([A-Z0-9_]+)$", path)
        if m:
            d = api_chain_detail(m.group(1), params)
            return self.send_json(d) if d else self.send_json({"error":"nicht gefunden"},404)

        m = re.match(r"^/api/songs/([^/]+)/playback$", path)
        if m:
            return self.send_json(api_playback(m.group(1)))

        m = re.match(r"^/songs/(.+)$", path)
        if m:
            f = JOBS_DIR / m.group(1)
            if f.exists() and f.is_file(): return serve_file(self, f)
            return self.send_json({"error":"Datei nicht gefunden"},404)

        # Statische Dateien
        if path in ("/", "/index.html"):
            # Primär: eingebettetes HTML (immer verfügbar in der .exe)
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(_INDEX_HTML)))
            self.send_header("Access-Control-Allow-Origin", "*")
            self.end_headers()
            self.wfile.write(_INDEX_HTML)
            return
            # Fallback: minimale Fehlerseite
            paths_str = "<br>".join(str(c) for c in candidates)
            html_str = (
                "<!DOCTYPE html><html><head><meta charset=UTF-8><title>FREDDY</title>"
                "<style>body{font-family:sans-serif;padding:40px;background:#1C1B18;"
                "color:#F1EFE8}h1{color:#534AB7}</style></head>"
                "<body><h1>FREDDY v2.0</h1>"
                "<p>Server laeuft — web/index.html nicht gefunden.</p>"
                "<p>Pfade: " + paths_str + "</p>"
                "</body></html>"
            )
            html = html_str.encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(html)))
            self.end_headers()
            self.wfile.write(html)
            return
        f = WEB_DIR / path.lstrip("/")
        if f.exists() and f.is_file(): return serve_file(self, f)
        # Auch neben exe probieren
        f2 = Path(sys.executable).parent / "web" / path.lstrip("/")
        if f2.exists() and f2.is_file(): return serve_file(self, f2)
        self.send_json({"error":f"Nicht gefunden: {path}"},404)

    def do_POST(self):
        parsed = urllib.parse.urlparse(self.path)
        path   = parsed.path
        length = int(self.headers.get("Content-Length",0))
        body   = self.rfile.read(length)
        ct     = self.headers.get("Content-Type","")

        if path == "/api/midi/upload":
            return self.send_json(handle_upload_multi(body, ct))
        if path == "/api/musicxml/upload":
            return self.send_json(handle_musicxml_upload(body, ct))
        if path == "/api/text/upload":
            return self.send_json(handle_text_upload(body, ct))
        if path == "/api/midi/convert-note":
            try:   stems = json.loads(body.decode()).get("stems",[])
            except: stems = []
            return self.send_json(handle_note_batch(stems))
        if path == "/api/midi/primus":
            try:   stem = json.loads(body.decode()).get("stem","")
            except: stem = ""
            if not stem: return self.send_json({"error":"stem fehlt"},400)
            return self.send_json(handle_primus_handoff(stem))

        self.send_json({"error":"Unbekannte Route"},404)

